# CPU policy agent

`driver.py` is the collected JSON entry point. `syntax.py` defines the public language and input bounds without evaluating predicates. `compiler/compiler.py` contains the existing FAdo predicate constructors and serial policy reduction. `ebpf/create_dfa.py` compiles and exports useful states. `ebpf/helper.py` installs transition cells in a memory backend and has an incomplete Agent interface.

Implement the complete versioned control-plane contract in `/workspace/PROTOCOL.md`. Kernel attachment, service deployment and packet capture are outside this project. You may edit every file in this directory and add ordinary files. The offline packages are already supplied; do not install dependencies. Run `python3 /workspace/launch.py < request.json` and `python3 /workspace/public_check.py` as a nonroot user. The starter is intentionally incomplete and is expected to fail the final contract.
=== driver.py ===
"""JSON batch entry point; policy/runtime modules implement the system."""
import json,math,re,sys
from ebpf.helper import Agent
from syntax import parse
U32=4294967295
LIMITS={'images':16,'cells':262144,'units':1024,'contexts':32768,'connections':4096,'packets':32768,'files':8192}
NAME=re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\Z')
SCHEMA={
 'stage':{'epoch':'positive','policy':'text'},'commit':{'epoch':'positive'},'retire':{'epoch':'positive'},
 'spawn':{'unit':'unit','service':'name'},'clone':{'parent':'unit','child':'unit'},'exit':{'unit':'unit'},
 'begin':{'unit':'unit','rid':'positive'},'finish':{'unit':'unit','rid':'positive'},
 'open':{'connection':'pair'},'close':{'connection':'pair'},
 'send':{'unit':'unit','rid':'positive','connection':'pair','stream':'positive','destination':'name'},
 'recv':{'unit':'unit','rid':'positive','connection':'pair','stream':'positive','wire':'wire'},
 'store':{'unit':'unit','rid':'positive','file':'pair'},'load':{'unit':'unit','rid':'positive','file':'pair'},
 'unlink':{'file':'pair'},'inspect':{}}
class Invalid(ValueError):pass

def require(ok):
 if not ok:raise Invalid()

def integer(v,lo=1,hi=U32):return type(v) is int and lo<=v<=hi

def typed(v,kind):
 if kind=='positive':return integer(v)
 if kind=='name':return type(v) is str and NAME.fullmatch(v) is not None
 if kind=='text':
  if type(v) is not str:return False
  v.encode('utf-8')
  return True
 if kind=='wire':return v is None or type(v) is str and len(v)<=96
 if kind=='pair':return type(v) is list and len(v)==2 and all(integer(x) for x in v)
 if kind=='unit':return type(v) is list and len(v)==3 and integer(v[0],0) and integer(v[1]) and integer(v[2])
 return False

def validate(job):
 require(type(job) is dict and set(job)=={'services','limits','events'})
 services=job['services'];limits=job['limits'];events=job['events']
 require(type(services) is list and 1<=len(services)<=16)
 names=set();labels=set()
 for service in services:
  require(type(service) is dict and set(service)=={'name','label'})
  require(typed(service['name'],'name') and integer(service['label'],1,U32-1))
  require(service['name'] not in names and service['label'] not in labels)
  names.add(service['name']);labels.add(service['label'])
 require(type(limits) is dict and set(limits)==set(LIMITS))
 for k,v in limits.items():require(integer(v,1,LIMITS[k]))
 require(type(events) is list and len(events)<=200000)
 for e in events:
  require(type(e) is dict and type(e.get('op')) is str and e['op'] in SCHEMA)
  fields=SCHEMA[e['op']];require(set(e)==set(fields)|{'op'})
  for k,kind in fields.items():require(typed(e[k],kind))
 atoms=symbols=0
 for e in events:
  if e['op']=='stage':
   try:
    tree,a,s=parse(e['policy']);atoms+=a;symbols+=s
   except Exception:pass
 return len(events),sum(len(e['policy'].encode('utf-8')) for e in events if e['op']=='stage'),sum(e['op']=='stage' for e in events),atoms,symbols

def unique(pairs):
 d={}
 for k,v in pairs:
  require(k not in d);d[k]=v
 return d

def invalid_constant(text):raise Invalid()

def float_number(text):
 v=float(text);require(math.isfinite(v));return v

def check_json_nesting(text):
 depth=0;quoted=False;escaped=False
 for char in text:
  if quoted:
   if escaped:escaped=False
   elif char=='\\':escaped=True
   elif char=='"':quoted=False
  elif char=='"':quoted=True
  elif char in '[{':
   depth+=1;require(depth<=64)
  elif char in ']}':
   depth-=1;require(depth>=0)
 require(depth==0 and not quoted)

def solve(data):
 try:
  require(len(data)<=24*1024**2)
  text=data.decode('utf-8');check_json_nesting(text)
  request=json.loads(text,object_pairs_hook=unique,parse_constant=invalid_constant,parse_float=float_number)
  require(type(request) is dict and set(request)=={'jobs'} and type(request['jobs']) is list and len(request['jobs'])<=4)
 except Exception:return {'error':'invalid'}
 results=[];total_events=0;total_policy_bytes=0;total_stages=0;total_rules=0;total_symbols=0
 validity=[]
 for job in request['jobs']:
  try:
   count,size,stages,rules,symbols=validate(job);total_events+=count;total_policy_bytes+=size;total_stages+=stages;total_rules+=rules;total_symbols+=symbols;validity.append(True)
  except Exception:validity.append(False)
 if total_events>200000 or total_policy_bytes>8*1024**2 or total_stages>16 or total_rules>32768 or total_symbols>65536:return {'error':'invalid'}
 for job,valid in zip(request['jobs'],validity):
  if not valid:results.append({'error':'invalid'});continue
  agent=Agent(job['services'],job['limits'])
  results.append({'events':[agent.event(e) for e in job['events']]})
 return {'results':results}

if __name__=='__main__':
 try:result=solve(sys.stdin.buffer.read(24*1024**2+1))
 except Exception:raise
 sys.stdout.write(json.dumps(result,separators=(',',':'),ensure_ascii=True)+'\n')
=== syntax.py ===
"""Policy syntax and declared bounds; no predicate evaluation or compilation."""
from lark import Lark,Tree
grammar = r'''
start: policy*
policy: predicate action ";"
?predicate: "(" predicate "and" predicate ")" -> and_
          | "(" predicate "or" predicate ")" -> or_
          | "not" "(" predicate ")" -> not_
          | atom
?atom: "match" "(" ph ")" -> match
     | "startswith" "(" ph ")" -> startswith
     | "endswith" "(" ph ")" -> endswith
     | "contains" "(" ph ")" -> contains
ph: [IDENT ("," IDENT)*]
action: "allow" -> allow
      | "drop" -> drop
IDENT: /[A-Za-z][A-Za-z0-9]{0,23}/
%import common.WS
%ignore WS
'''
PARSER=Lark(grammar,parser='lalr',maybe_placeholders=False)
class PolicyError(ValueError): pass

def parse(text,names=None):
    # Every valid rule contains an atom; parentheses nest at most predicate depth.
    # Reject declared format limits before constructing an unbounded parse tree.
    if text.count(';')>32768:raise PolicyError('rule bound')
    depth=0
    for char in text:
        if char=='(':
            depth+=1
            if depth>16:raise PolicyError('depth')
        elif char==')':
            depth-=1
            if depth<0:raise PolicyError('syntax')
    if depth:raise PolicyError('syntax')
    try:tree=PARSER.parse(text)
    except Exception as exc:raise PolicyError('syntax') from exc
    nonliteral=set();complex_count=0;path_symbols=0;atoms=0
    for policy in tree.children:
        pred=policy.children[0]
        simple=pred.data=='match'
        if not simple:complex_count+=1
        stack=[(pred,1)];local=0
        while stack:
            node,depth=stack.pop()
            if depth>16:raise PolicyError('depth')
            if node.data in ('match','startswith','endswith','contains'):
                path=[str(t) for t in node.children[0].children]
                if len(path)>16 or (names is not None and any(t not in names for t in path)):raise PolicyError('path')
                path_symbols+=len(path);atoms+=1;local+=1
                if node.data!='match':
                    if len(path)>4:raise PolicyError('nonliteral length')
                    nonliteral.add((str(node.data),tuple(path)))
            else:
                stack.extend((c,depth+1) for c in node.children if isinstance(c,Tree))
        if not simple and local>32:raise PolicyError('expression')
    if complex_count>8 or len(nonliteral)>4 or atoms>32768 or path_symbols>65536:raise PolicyError('bounds')
    return tree,atoms,path_symbols

from FAdo.fa import DFA, NFA
from functools import reduce
from lark import Transformer, Lark

class AlphabetGatherer(Transformer):
    def start(self, items):
        return set.union(*items)

    def policy(self, items):
        return items[0]

    def drop(self, items):
        return set()

    def allow(self, items):
        return set()

    def match(self, items):
        return items[0]

    def startswith(self, items):
        return items[0]

    def endswith(self, items):
        return items[0]

    def contains(self, items):
        return items[0]

    def and_(self, items):
        return items[0] | items[1]

    def or_(self, items):
        return items[0] | items[1]

    def ph(self, items):
        return set(items)

    def IDENT(self, tok):
        return str(tok)

    def NEWLINE(self, tok):
        return set()

def union(items):
    return reduce(lambda x, y: (x | y).minimal(), items)

def intersection(items):
    return reduce(lambda x, y: (x & y).minimal(), items)

class DFATransformer(Transformer):
    def start(self, items):
        # merge all policies with deny-by-default mechanism

        allow = [x[0] for x in items if x!="NEWLINE" and x[1] == "ALLOW"]
        drop = [x[0] for x in items if x!="NEWLINE" and x[1] == "DROP"]

        allow_dfa = union(allow) if allow else None
        drop_dfa = intersection(drop) if drop else None

        if allow_dfa and drop_dfa:
            return (allow_dfa & drop_dfa).minimal()
        elif allow_dfa:
            return allow_dfa
        else:
            raise Exception("All policies are DROP, no ALLOW policy found.")

    def policy(self, items):
        # complement if drop
        if items[1] == "DROP":
            return ~items[0], "DROP"
        elif items[1] == "ALLOW":
            return items[0], "ALLOW"
        else:
            return items[0], "ALLOW"

    def drop(self, items):
        return "DROP"

    def allow(self, items):
        return "ALLOW"

    def match(self, items):
        # build dfa
        d = DFA()
        ph = items[0]
        d.setSigma(self.alphabet)

        d.addState('q0')
        d.setInitial(0)
        for i in range(1, len(ph)+1, 1):
            d.addState(f'q{i}')
            d.addTransition(i-1, ph[i-1], i)

        d.addFinal(len(ph))

        return d

    def startswith(self, items):
        # build dfa
        d = DFA()
        ph = items[0]
        d.setSigma(self.alphabet)

        d.addState('q0')
        d.setInitial(0)
        for i in range(1, len(ph)+1, 1):
            d.addState(f'q{i}')
            d.addTransition(i-1, ph[i-1], i)
        d.addFinal(len(ph))

        for p in self.alphabet:
            d.addTransition(len(ph), p, len(ph))

        return d

    def endswith(self, items):
        # build nfa
        n = NFA()
        ph = items[0]
        n.setSigma(self.alphabet)

        n.addState('q0')
        n.setInitial([0])
        for p in self.alphabet:
            n.addTransition(0, p, 0)

        n.addState('q1')
        n.addTransition(0, "@epsilon", 1)
        for i in range(len(ph)):
            n.addState(f'q{i+2}')
            n.addTransition(i+1, ph[i], i+2)

        n.addFinal(len(ph)+1)
        return n.toDFA()

    def contains(self, items):
        # build nfa
        n = NFA()
        ph = items[0]
        n.setSigma(self.alphabet)
        n.addState('q0')

        n.setInitial([0])

        for p in self.alphabet:
            n.addTransition(0, p, 0)

        n.addState('q1')
        n.addTransition(0, "@epsilon", 1)
        for i in range(len(ph)):
            n.addState(f'q{i+2}')
            n.addTransition(i+1, ph[i], i+2)

        n.addFinal(len(ph)+1)

        for p in self.alphabet:
            n.addTransition(len(ph)+1, p, len(ph)+1)

        return n.toDFA()

    def and_(self, items):
        # intersect
        dfa = items[0] & items[1]
        return dfa.minimal()

    def or_(self, items):
        # union
        dfa = items[0] | items[1]
        return dfa.minimal()

    def ph(self, items):
        return items

    def IDENT(self, tok):
        return str(tok)

    def NEWLINE(self, tok):
        return "NEWLINE"

    def transform_with_alphabet(self, tree, alphabet):
        # set alphabet to all DFAs
        self.alphabet = alphabet
        return self.transform(tree)



grammar = r"""
    start: policy";" (NEWLINE policy";")* NEWLINE?

    policy: predicate action              -> policy

    // -------- predicates --------
    ?predicate: "(" predicate "and" predicate  ")" -> and_
        |     | "(" predicate "or"  predicate  ")"  -> or_
              | atom

    atom: "match"      "(" ph ")" -> match
        | "startswith" "(" ph ")" -> startswith
        | "endswith"   "(" ph ")" -> endswith
        | "contains"   "(" ph ")" -> contains

    // -------- action --------
    action: "drop" -> drop
          | "allow" -> allow

    // -------- PH --------
    ph: IDENT ("," IDENT)*
    IDENT: /[A-Za-z][A-Za-z0-9]*/

    NEWLINE: /(\r?\n)+/

    %import common.WS_INLINE
    %ignore WS_INLINE
"""


=== create_dfa.py ===
import os
import sys

# Reuse the full policy-language compiler in ../compiler (grammar, predicate/DFA
# construction, and union/intersection ops). We only replace its parallel
# tree-reduction with a serial merge so the eBPF agent never spawns processes.
_COMPILER_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "compiler"))
if _COMPILER_DIR not in sys.path:
    sys.path.insert(0, _COMPILER_DIR)

from lark import Lark
import compiler as C

POLICY_DIR = "ebpf/access_control/"

_parser = Lark(C.grammar, start="start")


class _SerialDFATransformer(C.DFATransformer):
    """Same semantics as compiler.DFATransformer, but merges policies serially
    (deny-by-default: union the ALLOW DFAs, intersect the complemented DROP DFAs,
    then intersect the two). Avoids the ProcessPool used for large-scale compiles."""

    def start(self, items):
        allow = [x[0] for x in items if x != "NEWLINE" and x[1] == "ALLOW"]
        drop = [x[0] for x in items if x != "NEWLINE" and x[1] == "DROP"]
        allow_dfa = C.union(allow) if allow else None
        drop_dfa = C.intersection(drop) if drop else None
        if allow_dfa and drop_dfa:
            return (allow_dfa & drop_dfa).minimal()
        elif allow_dfa:
            return allow_dfa
        else:
            raise Exception("All policies are DROP, no ALLOW policy found.")


def _compile(text, registry):
    tree = _parser.parse(text)
    alphabet = {s["name"] for s in registry}
    return _SerialDFATransformer().transform_with_alphabet(tree, alphabet)


def create(text, registry):
    dfa = _compile(text, registry)
    delta = dict(dfa.delta)
    useful = set(dfa.usefulStates())
    if dfa.Initial not in useful:
        raise ValueError("policy accepts no request path")

    def name(i):
        return "START" if i == dfa.Initial else f"q{i}"

    states = [name(i) for i in sorted(useful) if i != dfa.Initial]
    transitions = {}
    for s in useful:
        for symbol, target in delta.get(s, {}).items():
            if target not in useful:
                continue
            transitions.setdefault(name(s), {})[symbol] = name(target)
    order = [dfa.Initial] + [i for i in sorted(useful) if i != dfa.Initial]
    index = {i: n for n, i in enumerate(order)}
    names = [s['name'] for s in sorted(registry, key=lambda s: s['label'])]
    image = {'accept': [i in dfa.Final for i in order],
             'rows': [[index.get(delta.get(i, {}).get(a), 4294967295) for a in names] for i in order]}
    return image
=== helper.py ===
"""CPU map backend. Extend Agent to the full public lifecycle contract."""
import ctypes
from .create_dfa import create

class MemoryMap:
    def __init__(self): self.entries={}
    def __setitem__(self,key,value): self.entries[(key.st,key.t)]=value.value

class Agent:
    def __init__(self,services,limits):
        self.NAME_TO_LABEL={s['name']:s['label'] for s in services}
        self.services=services;self.limits=limits
        self.B={'access_control':MemoryMap()};self.images={};self.active=None

    def insert_multihop_policy(self,epoch,text):
        access_control_map=self.B['access_control']
        image=create(text,self.services)
        initial_state='START'
        states=['q'+str(i) for i in range(1,len(image['rows']))]
        def state_index(name):
            return 0 if name == "START" else states.index(name) + 1

        names = [s['name'] for s in sorted(self.services, key=lambda s: s['label'])]
        transitions = {}
        for i, row in enumerate(image['rows']):
            source = initial_state if i == 0 else states[i-1]
            transitions[source] = {
                name: (initial_state if target == 0 else states[target-1])
                for name, target in zip(names, row) if target != 4294967295
            }
        NAME_TO_LABEL = self.NAME_TO_LABEL

        class KeyT(ctypes.Structure):
            _fields_ = [("st", ctypes.c_uint32), ("t", ctypes.c_uint32)]

        for k, v in transitions.items():
            for inp, next_state in v.items():
                key = KeyT()
                key.st = state_index(k)
                key.t = NAME_TO_LABEL[inp]
                value = ctypes.c_uint32(state_index(next_state))
                access_control_map[key] = value

        self.images[epoch]=image
        return {'ok':True,'epoch':epoch,'image':image}

    def event(self,event):
        try:
            if event['op']=='stage':return self.insert_multihop_policy(event['epoch'],event['policy'])
            if event['op']=='commit' and event['epoch'] in self.images:
                self.active=event['epoch'];return {'ok':True}
            # Lifecycle operations and atomic capacity/version handling are unfinished.
            return {'error':'rejected'}
        except Exception:return {'error':'rejected'}

