    def _image(self, epoch):
        image = self.images.get(epoch)
        if image is None:
            raise Reject()
        return image

    def _unit(self, key):
        unit = self.units.get(key)
        if unit is None:
            raise Reject()
        return unit

    def _context(self, unit, rid):
        entry = unit.contexts.get(rid)
        if entry is None:
            raise Reject()
        return entry

    def _advance(self, image, state, service):
        return image.advance(state, self.column_of[service])

