    def op_stage(self, event):
        epoch = event['epoch']
        if epoch <= self.epoch_mark:
            raise Reject()
        try:
            image = create(event['policy'], self.registry)
        except PolicyError:
            raise Reject()
        accept = image['accept']
        rows = image['rows']
        if len(rows) > 8192:
            raise Reject()
