arguments.command:
cd /workspace/tmp/t && cat > fuzz.py <<'PYEOF'
"""Random event fuzz with an independent state model."""
import json, random, sys
sys.path.insert(0,'/opt/emicro-deps'); sys.path.insert(0,'/workspace/project')
import importlib.util
spec=importlib.util.spec_from_file_location('drv','/workspace/project/driver.py')
drv=importlib.util.module_from_spec(spec); spec.loader.exec_module(drv)

LIM={'images':16,'cells':262144,'units':1024,'contexts':32768,'connections':4096,'packets':32768,'files':8192}
SERVICES=[{'name':'A','label':10},{'name':'B','label':4},{'name':'C','label':7}]
NAMES=['A','B','C']

def random_event(rnd):
    op = rnd.choice(['stage','commit','retire','spawn','clone','exit','begin','finish',
                     'open','send','recv','close','store','load','unlink','inspect'])
    if op=='stage': return {'op':op,'epoch':rnd.randint(1,4),'policy':rnd.choice(['match(A) allow;','match(A,B) allow;','match(B) drop;','startswith(A) allow;',''])}
    if op in ('commit','retire'): return {'op':op,'epoch':rnd.randint(1,4)}
    if op=='spawn': return {'op':op,'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'service':rnd.choice(NAMES)}
    if op=='clone': return {'op':op,'parent':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'child':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)]}
    if op=='exit': return {'op':op,'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)]}
    if op in ('begin','finish'): return {'op':op,'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'rid':rnd.randint(1,4)}
    if op=='open': return {'op':op,'connection':[rnd.randint(1,2),rnd.randint(1,3)]}
    if op=='close': return {'op':op,'connection':[rnd.randint(1,2),rnd.randint(1,3)]}
    if op=='send': return {'op':op,'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'rid':rnd.randint(1,4),'connection':[rnd.randint(1,2),rnd.randint(1,3)],'stream':rnd.randint(1,4),'destination':rnd.choice(NAMES)}
    if op=='recv': return {'op':op,'connection':[rnd.randint(1,2),rnd.randint(1,3)],'stream':rnd.randint(1,4),'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'rid':rnd.randint(1,4),'wire':None if rnd.random()<0.5 else '00'*24}
    if op=='store': return {'op':op,'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'rid':rnd.randint(1,4),'file':[rnd.randint(1,2),rnd.randint(1,3)]}
    if op=='load': return {'op':op,'file':[rnd.randint(1,2),rnd.randint(1,3)],'unit':[rnd.randint(0,2),rnd.randint(1,3),rnd.randint(1,3)],'rid':rnd.randint(1,4)}
    if op=='unlink': return {'op':op,'file':[rnd.randint(1,2),rnd.randint(1,3)]}
    return {'op':'inspect'}

bad=0
for trial in range(200):
    rnd=random.Random(trial)
    events=[random_event(rnd) for _ in range(120)]
    req={'jobs':[{'services':SERVICES,'limits':LIM,'events':events}]}
    out=drv.solve(json.dumps(req).encode())
    assert set(out)=={'results'}, out
    res=out['results'][0]
